//! ProcessingInstruction pseudo-attributes use native ordered state and CharacterData transactions.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->Value{p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<?display a='loaded'?><!doctype html><html><body><div>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://abort-timeout.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn pi_pseudo_attributes_reads_parse_order_entities_and_whole_input_errors(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var proto=ProcessingInstruction.prototype,names=['hasAttributes','getAttributeNames','getAttribute','setAttribute','removeAttribute','toggleAttribute','hasAttribute'],lengths=[0,0,1,2,1,1,1];for(var i=0;i<names.length;i++){var desc=Object.getOwnPropertyDescriptor(proto,names[i]);if(!desc||typeof desc.value!=='function'||desc.value.name!==names[i]||desc.value.length!==lengths[i]||!desc.writable||!desc.enumerable||!desc.configurable)throw 'native PI method descriptor';}
var pi=document.createProcessingInstruction('display','A="&amp;&lt;&gt;&quot;&apos;&#65;&#x1F600;" a=\'second\'');if(!pi.hasAttributes()||pi.getAttributeNames().join(',')!=='A,a'||pi.getAttribute('A')!=='&<>"\'A'+String.fromCharCode(55357,56832)||pi.getAttribute('a')!=='second'||pi.getAttribute('absent')!==null||pi.hasAttribute('absent'))throw 'ordered case-sensitive XML parser';var snapshot=pi.getAttributeNames();snapshot[0]='changed';if(pi.getAttributeNames()[0]!=='A'||pi.attributes!==undefined)throw 'native snapshot not Element attributes';
for(var data of ['a="1" a="2"','a="&unknown;"','a="<"','a="&#0;"','a="&#xD800;"','-odd="x"','a=unquoted','a="x"b="y"','a="x"\fb="y"']){pi.data=data;if(pi.hasAttributes()||pi.getAttributeNames().length||pi.getAttribute('a')!==null)throw 'whole input parse failure';}pi.data='raw="'+String.fromCharCode(55296)+'"';if(pi.getAttribute('raw').charCodeAt(0)!==55296)throw 'raw UTF16 value';
"#);}
#[test]
fn pi_pseudo_attributes_writes_serialize_and_reparse_only_on_character_data_changes(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var pi=document.createProcessingInstruction('display','a="first" b="second"');pi.setAttribute('a','&<>"');if(pi.data!=='a="&amp;&lt;&gt;&quot;" b="second"'||pi.getAttributeNames().join(',')!=='a,b')throw 'ordered escaped serialization';pi.removeAttribute('a');pi.setAttribute('a','last');if(pi.getAttributeNames().join(',')!=='b,a')throw 'remove then append order';if(pi.toggleAttribute('flag',false)||!pi.toggleAttribute('flag')||!pi.toggleAttribute('flag',true)||pi.toggleAttribute('flag'))throw 'toggle presence';var old=pi.data;pi.removeAttribute('absent');if(pi.data!==old)throw 'absent removal';for(var name of ['', 'a b','a=b','a/b','a>b',String.fromCharCode(0)]){var invalid=false;try{pi.setAttribute(name,'x');}catch(e){invalid=e instanceof DOMException&&e.name==='InvalidCharacterError';}if(!invalid)throw 'DOM local name validation';}pi.setAttribute('-odd','native');pi.setAttribute(String.fromCharCode(55296),'raw');document.body.setAttribute('title','unrelated mutation');if(pi.getAttribute('-odd')!=='native'||pi.getAttribute(String.fromCharCode(55296))!=='raw')throw 'map survives attribute-driven serialization and unrelated writes';var copy=pi.cloneNode();if(copy.hasAttributes())throw 'clone reparses serialized source';pi.data=pi.data;if(pi.hasAttributes())throw 'same data write reparses';pi.setAttribute('force','yes');if(pi.toggleAttribute('force',undefined)||pi.hasAttribute('force'))throw 'explicit undefined boolean force';
"#);}
#[test]
fn pi_pseudo_attributes_character_data_aliases_splices_ranges_and_observer_records(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
for(var doc of [document,new Document(),document.createElement('template').content.ownerDocument,document.implementation.createDocument(null,'root',null),document.implementation.createHTMLDocument('inert')]){var pi=doc.createProcessingInstruction('display','a="one"'),observer=new MutationObserver(function(){});observer.observe(pi,{characterData:true,characterDataOldValue:true});var range=doc.createRange();range.setStart(pi,2);range.setEnd(pi,5);pi.setAttribute('a','two');var records=observer.takeRecords();if(records.length!==1||records[0].type!=='characterData'||records[0].target!==pi||records[0].oldValue!=='a="one"'||range.startOffset!==0||range.endOffset!==0)throw 'actual writer observation and range replacement';pi.nodeValue='b="two"';if(pi.getAttribute('b')!=='two'||pi.hasAttribute('a'))throw 'nodeValue map sync';pi.textContent='c="three"';if(pi.getAttribute('c')!=='three')throw 'textContent map sync';pi.appendData(' d="four"');if(pi.getAttribute('d')!=='four')throw 'append map sync';pi.insertData(0,'e="five" ');if(pi.getAttributeNames().join(',')!=='e,c,d')throw 'insert map sync';pi.deleteData(0,9);if(pi.hasAttribute('e'))throw 'delete map sync';pi.replaceData(0,pi.length,'z="last"');if(pi.getAttribute('z')!=='last')throw 'replace map sync';observer.disconnect();}
"#);}
#[test]
fn pi_pseudo_attributes_receiver_brand_and_conversion_order_preserve_domstrings(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var pi=document.createProcessingInstruction('display',''),set=ProcessingInstruction.prototype.setAttribute,get=ProcessingInstruction.prototype.getAttribute,log='',name={toString:function(){log+='N';return String.fromCharCode(55296);}},value={toString:function(){log+='V';return String.fromCharCode(56320);}},bad=false;try{set.call({},name,value);}catch(e){bad=e instanceof TypeError;}if(!bad||log)throw 'brand before conversions';set.call(pi,name,value);if(log!=='NV'||get.call(pi,String.fromCharCode(55296)).charCodeAt(0)!==56320)throw 'once ordered raw conversions';var missing=0;try{set.call(pi,'x');}catch(e){if(e instanceof TypeError)missing++;}try{get.call(pi);}catch(e){if(e instanceof TypeError)missing++;}if(missing!==2)throw 'required arguments';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,saved=child.ProcessingInstruction.prototype.setAttribute,conversions=0,arg={toString:function(){conversions++;return 'saved';}};saved.call(pi,'borrowed','yes');if(pi.getAttribute('borrowed')!=='yes')throw 'canonical child method on native receiver';var childError;try{saved.call(pi,'bad name','x');}catch(e){childError=e;}if(!(childError instanceof child.DOMException)||childError.name!=='InvalidCharacterError')throw 'method owner exception realm';
"#);p.set_location(&crate::navigation::address("https://other.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("saved.call(pi,arg,arg)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");p.set_location(&crate::navigation::address("https://abort-timeout.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"if(conversions||pi.hasAttribute('saved'))throw 'owner guard before author conversions';pi.setAttribute('fresh','yes');");}
#[test]
fn pi_pseudo_attributes_resource_refusal_preserves_data_map_ranges_and_observers(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var pi=document.createProcessingInstruction('display','a="old"'),observer=new MutationObserver(function(){});observer.observe(pi,{characterData:true,characterDataOldValue:true});if(pi.getAttribute('a')!=='old')throw 'initialize native map';var range=document.createRange();range.setStart(pi,2);range.setEnd(pi,4);"#);let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())}assert!(p.runtime.execute("pi.setAttribute('long-new-name','a larger new value')",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,r#"if(pi.data!=='a="old"'||pi.getAttributeNames().join(',')!=='a'||pi.getAttribute('a')!=='old'||range.startOffset!==2||range.endOffset!==4||observer.takeRecords().length)throw 'writer refusal atomic state';pi.setAttribute('fresh','recovered');if(pi.getAttribute('fresh')!=='recovered'||observer.takeRecords().length!==1)throw 'fresh native recovery';"#);}

 // A held native proposal must refund its complete unpublished payload when
 // the shared CharacterData transaction cannot be admitted.
 let(mut d,mut f,mut p)=fixture();let Value::Host(pi)=run(&mut d,&mut f,&mut p,r#"var pi=document.createProcessingInstruction('display','a="old"');pi.getAttribute('a');pi;"#)else{panic!("genuine PI")};p.begin_job();let before=p.state.retained;
 let prepared=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.prepare_pi(pi,"\0PI.setAttribute",&[Value::String("new".into()),Value::String("staged".into())]).unwrap();assert!(matches!(prepared,processing_instruction_interface::Prepared::Write{..}));assert!(p.state.retained>before);assert!(p.state.pi_pending.is_some());Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.finish_pi(pi,false);drop(prepared);assert!(p.state.pi_pending.is_none());assert_eq!(p.state.retained,before);run(&mut d,&mut f,&mut p,r#"if(pi.data!=='a="old"'||pi.hasAttribute('new'))throw 'discarded native proposal';pi.setAttribute('fresh','yes');"#);
}
#[test]
fn pi_pseudo_attributes_clones_imports_and_whole_range_copies_parse_independently(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var loaded=document.firstChild;if(loaded.nodeType!==7||loaded.target!=='display'||loaded.getAttribute('a')!=='loaded')throw 'actual loaded native PI parser';loaded.setAttribute('loaded','yes');if(loaded.getAttribute('loaded')!=='yes')throw 'actual loaded PI writer';var source=document.createProcessingInstruction('display','a="source"'),clone=source.cloneNode(true),doc=document.implementation.createDocument(null,'root',null),imported=doc.importNode(source,true);if(clone.ownerDocument!==document||imported.ownerDocument!==doc||clone.getAttribute('a')!=='source'||imported.getAttribute('a')!=='source')throw 'clone import native map';clone.setAttribute('a','clone');imported.data='b="import"';if(source.getAttribute('a')!=='source'||clone.getAttribute('a')!=='clone'||imported.getAttribute('b')!=='import')throw 'independent copied maps';var fragment=document.createDocumentFragment();fragment.appendChild(source);var range=document.createRange();range.selectNode(source);var content=range.cloneContents(),copied=content.firstChild;if(copied.nodeType!==7||copied.target!=='display'||copied.getAttribute('a')!=='source'||copied===source)throw 'whole leaf Range clone reparses';
"#);}
